SELECT SUM(o.Total) AS Revenue
FROM Orders o
JOIN OrderLines l ON l.OrderId = o.Id;

SELECT Day, Amount,
       SUM(Amount) OVER (ORDER BY Day) AS RunningTotal
FROM DailySales;

SELECT Month, Amount,
       LAG(Amount, 1, 0) OVER (ORDER BY Month) AS Prev
FROM MonthlySales;

SELECT c.Name, o.OrderId
FROM dbo.Customers c
CROSS APPLY dbo.OrdersForCustomer(c.CustomerId) o;

WITH d AS (
  SELECT Id, ROW_NUMBER() OVER (PARTITION BY Email ORDER BY Id) AS rn
  FROM Customers
)
DELETE FROM d WHERE rn > 1;

SELECT *
FROM Sales
PIVOT (SUM(Amount) FOR Quarter IN ([Q1], [Q2])) p;
